import { rmSync } from 'node:fs';
import { join } from 'node:path';

const buildDir = join(process.cwd(), 'build');

// _redirects is generated by scripts/gen-seo-assets.mjs and carries the legacy
// WordPress 301s. It used to be purged here as a Netlify leftover; it must now
// survive into the build output.
const stalePaths = [
  'assets/al_opt_content',
  'assets/backup',
];

for (const relativePath of stalePaths) {
  rmSync(join(buildDir, relativePath), {
    force: true,
    recursive: true,
  });
}

console.log('[cloudflare] prepared Worker build output');
